import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.CYjxsSA2.js";const g=JSON.parse('{"title":"项目管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/project.md","filePath":"guide/project.md"}'),n={name:"guide/project.md"};function d(l,t,s,i,h,p){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="项目管理" tabindex="-1">项目管理 <a class="header-anchor" href="#项目管理" aria-label="Permalink to &quot;项目管理&quot;">​</a></h1><p>项目是 VAELOR 的顶层组织单元 —— 所有扫描结果、军团会话与漏洞数据都归属于某个项目，天然隔离、互不干扰。</p><h2 id="项目列表" tabindex="-1">项目列表 <a class="header-anchor" href="#项目列表" aria-label="Permalink to &quot;项目列表&quot;">​</a></h2><p>首页即项目列表：</p><ul><li><strong>创建 / 归档</strong> —— 按客户、按阶段组织作业单元；项目状态分<strong>活跃 / 已归档</strong></li><li><strong>项目 ID</strong> —— 项目卡上可直接看到并一键复制，便于与他人核对同一次作业</li><li><strong>概况统计</strong> —— 项目卡上给出资产与漏洞概况</li><li><strong>脱敏显示</strong> —— 侧栏项目名可一键切换脱敏，适合演示与录屏</li></ul><h2 id="项目仪表盘" tabindex="-1">项目仪表盘 <a class="header-anchor" href="#项目仪表盘" aria-label="Permalink to &quot;项目仪表盘&quot;">​</a></h2><p>进入项目后的第一屏。整页恒为一屏，内容在面板内部滚动：</p><p><strong>顶部指标轨</strong> —— 活跃任务、资产、漏洞等关键数字连成一条，每个数字附带构成比例，点击可跳到对应面板。</p><p><strong>五个分区</strong>：</p><table tabindex="0"><thead><tr><th>分区</th><th>内容</th></tr></thead><tbody><tr><td><strong>概览</strong></td><td>模型用量趋势、风险构成、今日流量、近 30 天作业趋势</td></tr><tr><td><strong>资产态势</strong></td><td>攻击面雷达、攻击面分布、测绘概览、今日扫描活动</td></tr><tr><td><strong>风险线索</strong></td><td>TOP5 风险网站、TOP5 漏洞，点击可跳转对应模块</td></tr><tr><td><strong>动态</strong></td><td>军团与各模块的近期动作时间线</td></tr><tr><td><strong>工具矩阵</strong></td><td>常用模块的快捷入口</td></tr></tbody></table><h2 id="目标从哪来" tabindex="-1">目标从哪来 <a class="header-anchor" href="#目标从哪来" aria-label="Permalink to &quot;目标从哪来&quot;">​</a></h2><p>平台<strong>不设单独的目标录入页</strong> —— 目标在你下发扫描、测绘或让军团作业时自动登记到项目里：</p><ul><li>空间扫描填入的 IP / CIDR / 域名</li><li>空间测绘拉回的资产</li><li>军团在作业中发现的站点与主机</li></ul><p>登记后的目标可被各模块引用，也可被桌宠读取（「这个项目有哪些目标」）。</p><h2 id="扫描现场" tabindex="-1">扫描现场 <a class="header-anchor" href="#扫描现场" aria-label="Permalink to &quot;扫描现场&quot;">​</a></h2><p>各扫描类面板的页签布局会自动保存，下次进入时恢复现场。</p><h2 id="数据位置" tabindex="-1">数据位置 <a class="header-anchor" href="#数据位置" aria-label="Permalink to &quot;数据位置&quot;">​</a></h2><p>每个项目的数据（资产、扫描结果、漏洞、会话）都在数据目录内按项目分开存放，导出的报告与结果另有一处固定目录。备份或迁移时把整个数据目录带走即可。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>数据目录的位置与迁移方式见<a href="/vaelor/download.html#数据目录">下载与安装</a>。</p></div>',19)])])}const u=a(n,[["render",d]]);export{g as __pageData,u as default};
